import { DataError } from "./errors.ts";

/** One line of the ledger. Amounts are kept in cents to avoid float drift. */
export interface Expense {
  date: string;
  category: string;
  description: string;
  cents: number;
}

const HEADER = ["date", "category", "description", "amount"];
const AMOUNT = /^-?\d+(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Split one CSV line into fields; double quotes wrap fields that contain commas. */
export function splitLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') {
        current += '"';
        i++;
      } else if (ch === '"') {
        quoted = false;
      } else {
        current += ch;
      }
    } else if (ch === '"') {
      quoted = true;
    } else if (ch === ",") {
      fields.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  fields.push(current);
  return fields;
}

/** Parse an amount such as "12.50" into cents. */
export function parseCents(text: string): number {
  if (!AMOUNT.test(text)) {
    throw new DataError(`not an amount: ${text}`);
  }
  return Math.round(Number(text) * 100);
}

/** Parse the text of a ledger file (header line date,category,description,amount). */
export function parseLedger(text: string, name = "ledger"): Expense[] {
  const lines = text.split(/\r?\n/).filter((line) => line.trim() !== "");
  if (lines.length === 0 || splitLine(lines[0] ?? "").join(",") !== HEADER.join(",")) {
    throw new DataError(`${name}: the first line must be ${HEADER.join(",")}`);
  }
  return lines.slice(1).map((line, index) => {
    const fields = splitLine(line);
    const where = `${name}:${index + 2}`;
    if (fields.length !== HEADER.length) {
      throw new DataError(`${where}: expected ${HEADER.length} fields, found ${fields.length}`);
    }
    const [date, category, description, amount] = fields as [string, string, string, string];
    if (!DATE.test(date)) {
      throw new DataError(`${where}: bad date ${date}`);
    }
    try {
      return { date, category: category.trim(), description, cents: parseCents(amount) };
    } catch (error) {
      throw new DataError(`${where}: ${(error as Error).message}`);
    }
  });
}

/** Text formatting helpers for the command line output. */

/** Format cents as a plain decimal with two places: 123456 -> "1234.56". */
export function formatCents(cents: number): string {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  return `${sign}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, "0")}`;
}

/** Pad text on the right to a width. */
export function padRight(text: string, width: number): string {
  return text.length >= width ? text : text + " ".repeat(width - text.length);
}

/** Pad text on the left to a width. */
export function padLeft(text: string, width: number): string {
  return text.length >= width ? text : " ".repeat(width - text.length) + text;
}

/**
 * Render rows as a table: the first column is left-aligned, the others right-aligned,
 * every column is as wide as its widest cell, and columns are separated by two spaces.
 */
export function renderTable(header: string[], rows: string[][]): string {
  const widths = header.map((title, col) =>
    Math.max(title.length, ...rows.map((row) => (row[col] ?? "").length)),
  );
  const line = (cells: string[]) =>
    cells
      .map((cell, col) => (col === 0 ? padRight(cell, widths[col]!) : padLeft(cell, widths[col]!)))
      .join("  ")
      .trimEnd();
  return [line(header), ...rows.map(line)].join("\n");
}

